/* ───────── model ───────── */
function newState(dir) {
  var s = { L: {}, R: {}, Par: {} };
  ALLIDS.forEach(function (i) { s.L[i] = null; s.R[i] = null; s.Par[i] = null; });
  if (dir === 'left') {
    s.L.P = 'x'; s.Par.x = 'P';
    s.L.x = 'alpha'; s.Par.alpha = 'x'; s.R.x = 'y'; s.Par.y = 'x';
    s.L.y = 'beta'; s.Par.beta = 'y'; s.R.y = 'gamma'; s.Par.gamma = 'y';
  } else {
    s.L.P = 'y'; s.Par.y = 'P';
    s.L.y = 'x'; s.Par.x = 'y'; s.R.y = 'gamma'; s.Par.gamma = 'y';
    s.L.x = 'alpha'; s.Par.alpha = 'x'; s.R.x = 'beta'; s.Par.beta = 'x';
  }
  return s;
}
function snapOf(s, kind, touched, links, msg) {
  return {
    L: Object.assign({}, s.L), R: Object.assign({}, s.R), Par: Object.assign({}, s.Par),
    kind: kind, touched: touched || [], links: links || [], msg: msg
  };
}
function setChildS(s, p, side, c) {
  var old = side === 'L' ? s.L[p] : s.R[p];
  if (old && old !== c) s.Par[old] = null;
  if (c) {
    var cp = s.Par[c];
    if (cp) { if (s.L[cp] === c) s.L[cp] = null; if (s.R[cp] === c) s.R[cp] = null; }
    s.Par[c] = p;
  }
  if (side === 'L') s.L[p] = c; else s.R[p] = c;
}
function replaceInParentS(s, o, n) {
  var pa = s.Par[o];
  if (!pa) throw new Error('no parent');
  var np = s.Par[n]; if (np) { if (s.L[np] === n) s.L[np] = null; if (s.R[np] === n) s.R[np] = null; }
  if (s.L[pa] === o) s.L[pa] = n; else s.R[pa] = n;
  s.Par[n] = pa; s.Par[o] = null;
}

/* ───────── scripted frames ───────── */
var NAMES = {
  left: ['before', 'y = x.right', 'beta reparented', 'parent relinked', 'x is y.left', 'after'],
  right: ['before', 'x = y.left', 'beta reparented', 'parent relinked', 'y is x.right', 'after']
};
function buildScripted(dir) {
  var s = newState(dir), f = [];
  if (dir === 'left') {
    f.push(snapOf(s, 'before', [], [], 'Before. x is the subtree root, y is its right child, and β hangs between them as y’s left child.'));
    f.push(snapOf(s, 'read', ['y'], [['x', 'y']], 'y = x.right. Nothing has moved yet — we only name the node that is about to become the new root.'));
    setChildS(s, 'x', 'R', 'beta');
    f.push(snapOf(s, 'write', ['beta', 'x'], [['x', 'beta']], 'x.right = y.left: β changes parents. This is the only subtree that moves; y is momentarily detached.'));
    replaceInParentS(s, 'x', 'y');
    f.push(snapOf(s, 'write', ['y'], [['P', 'y']], 'y is attached where x used to hang. Skip this line and the whole rotated subtree floats free of the tree.'));
    setChildS(s, 'y', 'L', 'x');
    f.push(snapOf(s, 'write', ['x', 'y'], [['y', 'x']], 'y.left = x: x descends. Three assignments, constant time — no subtree was ever traversed.'));
    f.push(snapOf(s, 'after', [], [], 'After. y is the subtree root, and the inorder walk still reads α, x, β, y, γ.'));
  } else {
    f.push(snapOf(s, 'before', [], [], 'Before. y is the subtree root, x is its left child, and β hangs between them as x’s right child.'));
    f.push(snapOf(s, 'read', ['x'], [['y', 'x']], 'x = y.left. Nothing has moved yet — we only name the node that is about to become the new root.'));
    setChildS(s, 'y', 'L', 'beta');
    f.push(snapOf(s, 'write', ['beta', 'y'], [['y', 'beta']], 'y.left = x.right: β changes parents. Mirror image of the left rotation; x is momentarily detached.'));
    replaceInParentS(s, 'y', 'x');
    f.push(snapOf(s, 'write', ['x'], [['P', 'x']], 'x is attached where y used to hang — the same parent link, flipped the other way.'));
    setChildS(s, 'x', 'R', 'y');
    f.push(snapOf(s, 'write', ['x', 'y'], [['x', 'y']], 'x.right = y: y descends. The original shape is back — the two rotations are exact inverses.'));
    f.push(snapOf(s, 'after', [], [], 'After. x is the subtree root, and the inorder walk still reads α, x, β, y, γ.'));
  }
  return f;
}
var SCRIPT = { left: buildScripted('left'), right: buildScripted('right') };
var STATIC = { left: newState('right'), right: newState('left') };

/* ───────── layout ───────── */
function occupied(pos, x, y) {
  for (var k in pos) { if (Math.hypot(pos[k].x - x, pos[k].y - y) < 75) return true; }
  return false;
}
function layoutFrame(fr, O) {
  var pos = {}, det = {}, links = [], cyc = [];
  var root = fr.L.P || fr.R.P || null;
  function place(id, x, y, depth, isDet) {
    pos[id] = { x: x, y: y, r: (id === 'x' || id === 'y') ? NR : LR, det: isDet };
    if (isDet) det[id] = 1;
    var dx = depth === 0 ? 100 : 78, dy = depth === 0 ? 100 : 105;
    ['L', 'R'].forEach(function (side, k) {
      var c = fr[side][id]; if (!c) return;
      if (pos[c]) { cyc.push([id, c]); return; }
      place(c, x + (k === 0 ? -dx : dx), y + dy, depth + 1, isDet);
      links.push({ a: id, b: c, det: isDet });
    });
  }
  if (root) place(root, O.x, O.y, 0, false);
  var claimed = {};
  ALLIDS.forEach(function (p) { if (fr.L[p]) claimed[fr.L[p]] = 1; if (fr.R[p]) claimed[fr.R[p]] = 1; });
  ['x', 'y', 'beta', 'alpha', 'gamma'].forEach(function (id) {
    if (pos[id] || claimed[id]) return;
    var cfg = (root === 'y') ? CFG.B : CFG.A, slot = cfg[id], px, py, dep;
    if (slot && !occupied(pos, O.x + slot[0], O.y + slot[1])) { px = O.x + slot[0]; py = O.y + slot[1]; dep = slot[2]; }
    else { px = O.x + (O.x > FW / 2 ? 140 : -140); py = O.y + 140; dep = 1; }
    place(id, px, py, dep, true);
  });
