      drawEdge(g, a, b, { color: HI, width: 2.5, dash: '5,5' });
    }
  });
  /* nodes */
  Object.keys(lay.pos).forEach(function (id) {
    drawNodeShape(g, id, lay.pos[id], { hi: !!hiN[id] });
  });
  /* detached markers */
  Object.keys(lay.det).forEach(function (id) {
    var p = lay.pos[id];
    var par = fr.Par[id];
    var isRoot = !(par && (fr.L[par] === id || fr.R[par] === id));
    if (!isRoot) return;
    g.text('detached').font({ family: SERIF, size: 15, style: 'italic', anchor: 'middle' }).fill(GHOSTC).center(p.x, p.y - p.r - 14);
  });
  /* violations */
  if (opt.violations) {
    opt.violations.forEach(function (id) {
      var p = lay.pos[id]; if (!p) return;
      g.circle(2 * (p.r + 9)).center(p.x, p.y).fill('none').stroke({ color: VIOL, width: 2.5 }).attr({ 'stroke-dasharray': '5,4' });
    });
  }
