  arrowHead(gu, 470, 130, -1, '#000');
  richText(gu, '<tspan style="font-variant:small-caps">Left-Rotate(</tspan><tspan font-style="italic">T</tspan><tspan>, </tspan><tspan font-style="italic">x</tspan><tspan>)</tspan>', 600, 92, 30);
  gl.line(465, 215, 720, 215).stroke({ color: '#000', width: 5, linecap: 'round' }).attr({ 'stroke-dasharray': '1,11' });
  arrowHead(gl, 730, 215, 1, '#000');
  richText(gl, '<tspan style="font-variant:small-caps">Right-Rotate(</tspan><tspan font-style="italic">T</tspan><tspan>, </tspan><tspan font-style="italic">y</tspan><tspan>)</tspan>', 600, 262, 30);
