  } else {
    lines = TRACE[rs.dir];
    cur = (rs.idx >= 1 && rs.idx <= 4) ? rs.idx : (rs.idx === 5 ? 5 : 0);
  }
  var y = 306;
  lines.forEach(function (ln, i) {
    var isHead = (i === 0 && rs.mode !== 'code') || (i === 0 && rs.mode === 'code');
    var col = '#000', op = 1;
    if (rs.mode === 'code') { col = (i === cur) ? HI : '#333'; op = (i === cur) ? 1 : 0.55; }
    else if (i > 0) { col = (i === cur) ? HI : '#000'; op = (i <= (cur === 5 ? 4 : cur)) ? 1 : 0.28; }
    var t = g.text(ln).font({ family: MONO, size: isHead ? 14 : 14, anchor: 'start' }).fill(col)
      .attr({ 'xml:space': 'preserve' }).move(478, y);
