/* ───────── inorder ribbon ───────── */
function drawRibbon(g, fr, O) {
  var lay = layoutFrame(fr, O);
  var items = Object.keys(lay.pos).map(function (id) { return { id: id, x: lay.pos[id].x, det: !!lay.pos[id].det }; });
  if (!items.length) return;
