        snap('write', [p].concat(c ? [c] : []), c ? [[p, c]] : [], 'setLeft(' + lbl(p) + ', ' + lbl(c) + ') — ' + lbl(c) + ' is now ' + lbl(p) + '.left');
      },
      setRight: function (p, c) {
        guard(); internal(p, 'setRight'); c = chk(c, 'setRight');
        var old = s.R[p]; if (old && old !== c) s.Par[old] = null;
        if (c) { detach(c); s.Par[c] = p; }
        s.R[p] = c;
        snap('write', [p].concat(c ? [c] : []), c ? [[p, c]] : [], 'setRight(' + lbl(p) + ', ' + lbl(c) + ') — ' + lbl(c) + ' is now ' + lbl(p) + '.right');
      },
      replaceInParent: function (o, n2) {
        guard(); chk(o, 'replaceInParent'); chk(n2, 'replaceInParent');
        var pa = s.Par[o];
        if (!pa) throw new Error('replaceInParent: ' + lbl(o) + ' has no parent (it is already detached)');
        if (s.L[pa] !== o && s.R[pa] !== o) throw new Error('replaceInParent: ' + lbl(o) + ' is no longer a child of ' + lbl(pa));
        if (n2) detach(n2);
        if (s.L[pa] === o) s.L[pa] = n2; else s.R[pa] = n2;
        if (n2) s.Par[n2] = pa;
        s.Par[o] = null;
        snap('write', n2 ? [n2] : [], (pa && n2) ? [[pa, n2]] : [], 'replaceInParent(' + lbl(o) + ', ' + lbl(n2) + ') — ' + lbl(n2) + ' now hangs on ' + lbl(pa));
      },
      note: function (t) { guard(); snap('note', [], [], String(t)); }
    };
    Object.freeze(api);
    var err = null;
    try {
      snap('before', [], [], 'Before: x is the subtree root, y is its right child.');
      var f = new Function('right', 'left', 'parent', 'setLeft', 'setRight', 'replaceInParent', 'note',
        '"use strict";' + src + '\nreturn typeof leftRotate==="function"?leftRotate:null;');
      var entry = f(api.right, api.left, api.parent, api.setLeft, api.setRight, api.replaceInParent, api.note);
      if (!entry) throw new Error('no function named leftRotate(T, x) was defined');
      entry({}, 'x');
    } catch (e) {
      err = (e && e.message) ? e.message : String(e);
      frames.push({
        L: Object.assign({}, s.L), R: Object.assign({}, s.R), Par: Object.assign({}, s.Par),
