}
function inorderOf(fr) {
  var out = [], seen = {};
  (function w(id) { if (!id || seen[id]) return; seen[id] = 1; w(fr.L[id]); out.push(id); w(fr.R[id]); })(fr.L.P || fr.R.P);
  return out;
}
function acceptFrames(data) {
  if (!data || !data.frames || !data.frames.length) { failFrames('⚠ no frames were recorded'); return; }
  rs.codeFrames = data.frames; rs.mode = 'code'; rs.dir = 'left';
  document.getElementById('directionInput').checked = false;
  var last = data.frames[data.frames.length - 1];
  var viol = [];
  if (last.L.P !== 'y') viol.push('y');
  if (last.L.y !== 'x') viol.push('x');
  if (last.R.y !== 'gamma') viol.push('gamma');
  if (last.L.x !== 'alpha') viol.push('alpha');
  if (last.R.x !== 'beta') viol.push('beta');
  var io = inorderOf(last).join(',');
  var ok = (viol.length === 0) && io === 'alpha,x,beta,y,gamma';
  rs.violations = viol;
  if (last.kind === 'error') setStatus('Status: error — ' + last.msg.replace('⚠ ', ''), '#c62828');
  else if (ok) setStatus('Status: correct ✓ inorder still α, x, β, y, γ', '#2e7d32');
  else setStatus('Status: wrong answer — broken: ' + viol.map(function (v) { return GLY[v]; }).join(', '), '#c62828');
  document.getElementById('runLog').textContent =
    data.frames.map(function (f, i) { return i + '  ' + (f.msg || ''); }).join('\n');
  document.getElementById('demoNarration').textContent = 'Code mode: scrub the frames below — each one is a single recorded operation. Press “Back to guided demo” to return to the narrated walkthrough.';
  document.getElementById('stepLabel').textContent = 'code trace';
  setIdx(0);
}
function failFrames(msg) {
  var s = newState('left');
  rs.codeFrames = [snapOf(s, 'error', [], [], msg)];
  rs.mode = 'code'; rs.violations = [];
  setStatus('Status: ' + msg, '#c62828');
  document.getElementById('runLog').textContent = msg;
  setIdx(0);
}
function trigger_runCode() {
  stopPlay();
  var btn = document.getElementById('runBtn');
  btn.disabled = true;
  setStatus('Status: running…', '#555');
  var code = document.getElementById('rotateCodeCode').value;
  var url;
  try {
    url = URL.createObjectURL(new Blob(['(' + workerBody.toString() + ')()'], { type: 'text/javascript' }));
  } catch (e) { btn.disabled = false; failFrames('⚠ cannot start worker: ' + e.message); return; }
  var w = new Worker(url), done = false;
  function finish() { done = true; try { w.terminate(); } catch (e) { } URL.revokeObjectURL(url); btn.disabled = false; }
  var to = setTimeout(function () { if (done) return; finish(); failFrames('⚠ timed out after 1.5 s — infinite loop?'); }, 1500);
  w.onmessage = function (e) { if (done) return; clearTimeout(to); finish(); acceptFrames(e.data); };
  w.onerror = function (e) { if (done) return; clearTimeout(to); finish(); failFrames('⚠ ' + (e.message || 'worker error')); };
  w.postMessage({ code: code });
}
function trigger_reset() {
  rs.mode = 'scripted'; rs.violations = []; rs.codeFrames = null;
  setStatus('Status: not run', '#555');
  document.getElementById('runLog').textContent = '';
  applyDemo(0);
}

/* ───────── init ───────── */
loadSample('sample');
applyDemo(0);
window.__markRendered();
// @FIGURE_CODE_END

