  B: { y: [0, 0, 0], x: [-DX0, DY0, 1], gamma: [DX0, DY0, 1], alpha: [-DX0 - DX1, DY0 + DY1, 2], beta: [-DX0 + DX1, DY0 + DY1, 2] }
};

